from libris.books.store import BookShelf
from libris.books.models import Book
def mk(n, cat='x'):
    s = BookShelf()
    for k in range(n):
        s.add(Book(id='k%02d' % k, title='N%02d' % k, genre=cat, copies=(k * 5) % 7, price=1.0 + k))
    return s
from libris.books.errors import Invalid
try:
    mk(0).add(Book(id='a', title='b', genre='c', copies=-1))
except Invalid as e:
    print(e)

